INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65325362', 65325362, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'JASA KONSULTAN PENYUSUNAN REKOMENDASI KEBIJAKAN PEMENUHAN GIZI NASIONAL LINTAS SEKTOR TAHUN 2026', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 90000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'a. Mengidentifikasi isu strategis dalam pelaksanaan MBG dan menyusun alternatif rekomendasi kebijakan b. Menginisiasi pengembangan rekomendasi kebijakan untuk disampaikan ke pengambil keputusan c. Membantu mengoordinasikan seluruh Konsultan dalam memproduksi analisis terkini dan penyusunan brief/laporan/publikasi media dan isu strategis MBG dari seluruh Konsultan d. Bersama Konsultan lain mengembangkan desain dan metodologi evaluasi dampak MBG yang reliabel e. Menjaga kualitas produksi brief/laporan yang disusun oleh Konsultan f. Membantu koordinasi substansi dan operasional dengan unit kerja di Bappenas yang mendukung penyelenggaraan MBG g. Melaksanakan kegiatan lainnya sesuai arahan pimpinan.', 'a. Pendidikan minimal S2 bidang kesehatan masyarakat/ kebijakan publik/ ilmu ekonomi/ ekonomi pembangunan/kesejahteraan sosial yang dibuktikan dengan ijazah. b. Memiliki pengalaman kerja minimal 13 (tiga belas) tahun dalam mengelola program kesehatan dan gizi masyarakat di tingkat nasional maupun daerah. Dibuktikan dengan kontrak kerja/surat referensi kerja. c. Memiliki pengalaman minimal 1 (satu) kali dalam 13 (tiga belas) tahun sebagai koordinator/manajer program yang terkait dengan bidang kesehatan masyarakat/kebijakan publik/gizi masyarakat/kebijakan kesehatan, termasuk pengalaman subkontrak dibuktikan dengan surat referensi/kontrak kerja sebelumnya. d. Memiliki kemampuan menulis artikel/ laporan/ presentasi dalam Bahasa Indonesia/ Bahasa Inggris yang dibuktikan dengan hasil tulisan artikel/laporan/presentasi. e. Berpengalaman dalam memfasilitasi dan menjalin hubungan kerjasama dengan lembaga internasional (bilateral, multilateral, ataupun lembaga non-profit internasional) yang dibuktikan dengan laporan pekerjaan/kontrak kerja sebelumnya f. Berpengalaman menjadi pembicara/delegasi dalam pertemuan internasional dan nasional yang dibuktikan dengan sertifikat/surat referensi; g. Memiliki pengalaman pekerjaan dengan nilai pekerjaan sejenis tertinggi dalam kurun waktu 10 (sepuluh) tahun terakhir paling kurang sama dengan 50% nilai total HPS/Pagu Anggaran h. Diutamakan Konsultan dalam negeri yang dibuktikan dengan identitas kewarganegaraan Indonesia sebagai Kartu Tanda Penduduk.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2081264);
